import{c as e,Q as a,j as d,m as o}from"./chunks/framework.8JjYC3xy.js";const u=JSON.parse('{"title":"第七章：上下文与会话管理","description":"看懂上下文窗口、压缩时机、会话恢复与回滚，让长任务不失控","frontmatter":{"title":"第七章：上下文与会话管理","description":"看懂上下文窗口、压缩时机、会话恢复与回滚，让长任务不失控"},"headers":[],"relativePath":"guide/2-basic-usage/7-multi-turn.md","filePath":"guide/2-basic-usage/7-multi-turn.md"}'),s={name:"guide/2-basic-usage/7-multi-turn.md"};function c(i,t,l,n,r,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="第七章-上下文与会话管理" tabindex="-1">第七章：上下文与会话管理 <a class="header-anchor" href="#第七章-上下文与会话管理" aria-label="Permalink to &quot;第七章：上下文与会话管理&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你能自己判断「该压缩还是该重开」，会用 <code>/resume</code>/<code>/rewind</code> 找回之前的任何状态，也知道怎么让多轮对话真正收敛到结果。</p></div><h2 id="为什么多轮对话更有效" tabindex="-1">为什么多轮对话更有效？ <a class="header-anchor" href="#为什么多轮对话更有效" aria-label="Permalink to &quot;为什么多轮对话更有效？&quot;">​</a></h2><p>想象你要建一座房子：</p><ul><li><strong>一次性描述</strong>：给我建一座房子 → 出来的可能不是你想要的</li><li><strong>一步步来</strong>：先打地基 → 地基好了继续砌墙 → 墙好了继续装修 → 每一步都能调整</li></ul><p>多轮对话就是这种方式。但它有个前提：<strong>Claude 的&quot;记忆&quot;是有容量的</strong>，这个容量叫上下文窗口。管不好它，多轮就会变成越聊越糊涂。</p><h2 id="场景演练-做一个待办事项" tabindex="-1">场景演练：做一个待办事项 <a class="header-anchor" href="#场景演练-做一个待办事项" aria-label="Permalink to &quot;场景演练：做一个待办事项&quot;">​</a></h2><h3 id="第一轮-基础结构" tabindex="-1">第一轮：基础结构 <a class="header-anchor" href="#第一轮-基础结构" aria-label="Permalink to &quot;第一轮：基础结构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一个待办事项的基本结构，先用 Python 命令行版本</span></span></code></pre></div><h3 id="第二轮-添加功能" tabindex="-1">第二轮：添加功能 <a class="header-anchor" href="#第二轮-添加功能" aria-label="Permalink to &quot;第二轮：添加功能&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>添加&quot;标记完成&quot;功能，已完成的项目在最上面</span></span></code></pre></div><p>它会基于现有代码继续改，不用你重新解释。</p><h3 id="第三轮-加一个可验证的标准" tabindex="-1">第三轮：加一个可验证的标准 <a class="header-anchor" href="#第三轮-加一个可验证的标准" aria-label="Permalink to &quot;第三轮：加一个可验证的标准&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>加上单元测试，跑 pytest 全绿了再告诉我</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">关键习惯</p><p>每一轮都给它一个<strong>能自己检查的标准</strong>（测试通过、命令输出、lint 无警告）。有标准它会自己迭代到对；没有标准它只能说&quot;我改好了&quot;，而它可能没改好。</p></div><h2 id="上下文窗口到底装了什么" tabindex="-1">上下文窗口到底装了什么 <a class="header-anchor" href="#上下文窗口到底装了什么" aria-label="Permalink to &quot;上下文窗口到底装了什么&quot;">​</a></h2><p>运行 <code>/context</code> 看实时占用。装的东西大致是：</p><table tabindex="0"><thead><tr><th>占位来源</th><th>说明</th><th>能不能省</th></tr></thead><tbody><tr><td>系统提示与工具定义</td><td>它自己的说明书，固定开销</td><td>不能</td></tr><tr><td><code>CLAUDE.md</code> 与记忆</td><td>每次会话自动加载</td><td>能，写短点</td></tr><tr><td>你读过的文件</td><td>读一次就留在窗口里</td><td>能，用 <code>@</code> 精确指定</td></tr><tr><td>工具输出</td><td>测试日志、命令结果，往往最占地方</td><td>能，让它只输出摘要</td></tr><tr><td>对话历史</td><td>你的提问和它的回复</td><td>靠压缩</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">别让一条命令撑爆上下文</p><p><code>cat 一个 10 万行的日志</code> 会直接把窗口吃掉大半。正确的做法是让它先 <code>grep</code> 或 <code>tail -200</code>，或者你自己在终端筛完再贴给它。</p></div><h2 id="什么时候压缩-什么时候重开" tabindex="-1">什么时候压缩，什么时候重开 <a class="header-anchor" href="#什么时候压缩-什么时候重开" aria-label="Permalink to &quot;什么时候压缩，什么时候重开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的情况</th><th>用哪个</th><th>效果</th></tr></thead><tbody><tr><td>还是同一个任务，只是聊长了</td><td><code>/compact</code></td><td>把历史总结成摘要，继续干</td></tr><tr><td>换了个不相关的任务</td><td><code>/clear</code></td><td>清空对话，保留 <code>CLAUDE.md</code> 和记忆</td></tr><tr><td>想回到某个之前的状态</td><td><code>/rewind</code></td><td>回滚代码 + 对话到检查点</td></tr><tr><td>想同时试两个方向</td><td><code>/branch</code></td><td>从当前对话分叉，原对话不动</td></tr></tbody></table><h3 id="compact-——-压缩" tabindex="-1"><code>/compact</code> —— 压缩 <a class="header-anchor" href="#compact-——-压缩" aria-label="Permalink to &quot;`/compact` —— 压缩&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/compact</span></span></code></pre></div><p>可以指定重点，比如 <code>/compact 保留数据库表结构那部分结论</code>。</p><p>Claude Code 默认也会<strong>自动压缩</strong>：窗口快满时自己总结一次。自动压缩经常触发、感觉越压越糊涂时，说明这个任务该拆了，或者你一开始就该用 <code>/clear</code> 重开并带上结论。</p><h3 id="clear-——-重开" tabindex="-1"><code>/clear</code> —— 重开 <a class="header-anchor" href="#clear-——-重开" aria-label="Permalink to &quot;`/clear` —— 重开&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/clear</span></span></code></pre></div><p>对话清空，但 <code>CLAUDE.md</code>、<code>.claude/</code> 配置、记忆都还在。换任务时用它，比在旧上下文里硬接着聊干净得多。</p><div class="tip custom-block"><p class="custom-block-title">重开前先留个交接</p><p>重开前让它写一段结论，粘到新会话开头：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这个任务的结论和下一步写成 5 行，我要开新会话接着做</span></span></code></pre></div></div><h2 id="会话能保存、能恢复、能分叉" tabindex="-1">会话能保存、能恢复、能分叉 <a class="header-anchor" href="#会话能保存、能恢复、能分叉" aria-label="Permalink to &quot;会话能保存、能恢复、能分叉&quot;">​</a></h2><p>会话会自动保存在本地，退出不会丢。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>claude --continue</code></td><td>直接接着<strong>当前目录</strong>最近一次会话</td></tr><tr><td><code>claude --resume</code></td><td>打开会话列表，挑一个恢复</td></tr><tr><td><code>claude --resume 名字</code></td><td>恢复指定名字的会话</td></tr><tr><td><code>/resume</code></td><td>在会话里切换到另一个会话</td></tr><tr><td><code>/branch</code></td><td>从当前对话分叉，去试另一个方向</td></tr><tr><td><code>/fork</code></td><td>复制当前对话到后台会话，这边继续干</td></tr><tr><td><code>/recap</code></td><td>生成当前会话的一句话摘要（离开一阵子回来用）</td></tr><tr><td><code>/export</code></td><td>导出对话为文本</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">给会话起名字</p><p><code>/clear 结账模块重构</code> 里的那个名字会成为会话标签，之后在 <code>/resume</code> 列表里一眼就能找到。长期项目尤其值得养成这个习惯。</p></div><h2 id="rewind-——-最常用的后悔药" tabindex="-1"><code>/rewind</code> —— 最常用的后悔药 <a class="header-anchor" href="#rewind-——-最常用的后悔药" aria-label="Permalink to &quot;`/rewind` —— 最常用的后悔药&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/rewind</span></span></code></pre></div><p>按 <code>Esc</code> 两次也能打开。它能回滚<strong>代码和对话</strong>到之前任意一个检查点，也可以只回滚其中一样。它还能&quot;从这里往后总结&quot;，把中间一大段压缩掉但保留结论。</p><p>什么时候用：</p><ul><li>它改了一大堆，你发现有 3 个文件改错了</li><li>聊歪了，想回到岔路口重来</li><li>想砍掉中间那段试错过程，只保留现在的结论</li></ul><div class="warning custom-block"><p class="custom-block-title">一个边界</p><p><code>/rewind</code> 管的是 Claude 自己做的改动。你自己在编辑器里手动改的文件不在它的回滚范围内。</p></div><h2 id="记忆-memory" tabindex="-1">记忆：<code>/memory</code> <a class="header-anchor" href="#记忆-memory" aria-label="Permalink to &quot;记忆：`/memory`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/memory</span></span></code></pre></div><p>打开记忆文件编辑界面，可以查看和修改：</p><ul><li><strong><code>CLAUDE.md</code></strong>（项目级）—— 团队共享的规则和背景</li><li><strong><code>CLAUDE.local.md</code></strong>（个人级，不进 git）—— 你个人的偏好</li><li><strong>自动记忆</strong> —— Claude 根据自己的更正经验自动记下的笔记，可以在这里查看、删除</li></ul><p>关于怎么写 <code>CLAUDE.md</code>，第十一章专门讲。</p><h2 id="高效交接模板" tabindex="-1">高效交接模板 <a class="header-anchor" href="#高效交接模板" aria-label="Permalink to &quot;高效交接模板&quot;">​</a></h2><p>换新会话时，开头给一段背景比让它重新摸索快得多：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我在做一个 Flask 博客项目，已经完成：</span></span>\n<span class="line"><span>1. 用户认证（JWT，代码在 app/auth/）</span></span>\n<span class="line"><span>2. 文章 CRUD（app/posts/）</span></span>\n<span class="line"><span>3. PostgreSQL + SQLAlchemy</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>当前问题：评论功能的权限判断不对，普通用户能看到别人的草稿评论。</span></span>\n<span class="line"><span>先定位原因，给方案，别急着改。</span></span></code></pre></div><p>比起&quot;帮我加评论功能&quot;，这段背景能让它少读几十个文件。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: 聊到后面它开始忘事、重复犯错？</strong></p><p>A: 上下文被老内容挤满了。先 <code>/context</code> 看占用，再决定 <code>/compact</code> 还是 <code>/clear</code> 重开。</p><p><strong>Q: 关掉终端会话就没了？</strong></p><p>A: 没丢。<code>claude --continue</code> 接着上次，或 <code>/resume</code> 挑。</p><p><strong>Q: 压缩之后它忘了我定的规则？</strong></p><p>A: <code>CLAUDE.md</code> 和记忆不受压缩影响（它们每次重新加载），只有对话历史会被总结。所以<strong>重要规则一定要写进 <code>CLAUDE.md</code>，不要只靠嘴上说</strong>。</p><p><strong>Q: 能不能同时开两个会话做不同的活？</strong></p><p>A: 能。多开终端窗口即可。想隔离同一个仓库的并行改动，用 git worktree，见第十九章。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>在一个会话里运行 <code>/context</code>，找出占用最大的那一项</li><li>干一件小事，退出，再用 <code>claude --continue</code> 接着聊</li><li>故意让它改错一个文件，用 <code>/rewind</code> 回滚</li><li>用 <code>/clear 我的任务名</code> 开新会话，然后在 <code>/resume</code> 列表里找到它</li></ol><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p><a href="/claude-code-guide/guide/3-practical-workflows/08-debugging.html">👉 第八章：调试和错误处理</a></p>',61)])])}const b=e(s,[["render",c]]);export{u as __pageData,b as default};
